/**
 * Inline-summary extraction for notification bodies.
 *
 * Notification bodies are Markdown (see the server's `formatActionApprovalBody`):
 * a leading one-sentence summary — "**An agent** wants to merge [Name](url)." —
 * followed by detail lines (`- Entity id: 886`), the proposer's reason, and a
 * "[Review in Lobu](url)" link. The timeline card shows only the first block;
 * the detail belongs in the focused/peek view, not in a two-line clamp.
 */

/** Trailing review CTA — its own affordance in the card, never summary prose. */
const REVIEW_LINK_LINE = /^\[Review in Lobu\]\(.*\)$/;

/** `- Label: value` detail lines that follow the summary sentence. */
const DETAIL_LINE = /^[-*]\s/;

/**
 * First meaningful block of a notification body: the summary sentence, with the
 * detail list, reason paragraph, and review link dropped. Markdown is preserved
 * (bold, links) for the caller to render — this only chooses *what* to show.
 *
 * Returns null when nothing renderable remains, so callers can skip the node
 * rather than render an empty paragraph.
 */
export function notificationSummaryMarkdown(
	body: string | null | undefined,
): string | null {
	if (!body) return null;

	const summary: string[] = [];
	for (const raw of body.split("\n")) {
		const line = raw.trim();
		// A blank line ends the summary block only once we have prose; leading
		// blanks are skipped so a body that opens with a newline still resolves.
		if (line === "") {
			if (summary.length > 0) break;
			continue;
		}
		if (DETAIL_LINE.test(line) || REVIEW_LINK_LINE.test(line)) break;
		summary.push(line);
	}

	// Bodies wrap the summary sentence across lines; rejoin so it reads as one
	// paragraph and the Markdown link syntax stays intact.
	const text = summary.join(" ").trim();
	return text === "" ? null : text;
}

import { describe, expect, it } from "vitest";
import { notificationSummaryMarkdown } from "./notification-summary";

/**
 * Inputs are the real server outputs — copied from the golden pins in
 * packages/server/src/__tests__/unit/approval-notification-render.test.ts and
 * from a production `Review merging person` card — so this stays honest about
 * the shape the timeline actually receives.
 */
describe("notificationSummaryMarkdown", () => {
	it("keeps the summary sentence and drops the detail list", () => {
		const body =
			"**An agent** wants to merge [905319918039@s.whatsapp.net](https://app.lobu.ai/buremba/person/member-0faa51dac0).\n" +
			"- Entity id: 886\n- Entity ids: [ 886 ]\n- Winner entity id: 315";
		expect(notificationSummaryMarkdown(body)).toBe(
			"**An agent** wants to merge [905319918039@s.whatsapp.net](https://app.lobu.ai/buremba/person/member-0faa51dac0).",
		);
	});

	it("drops the diff list from a field-change body", () => {
		const body =
			"**Watcher &lt;One&gt;** wants to update [App &amp; Crashes](https://app.lobu.ai/acme/topic/app-crashes):\n" +
			"- Severity: ~high~\n→ critical\n" +
			"\nField is protected: severity (currently set by you).\n" +
			"\n[Review in Lobu](https://app.lobu.ai/acme/runs/42)";
		expect(notificationSummaryMarkdown(body)).toBe(
			"**Watcher &lt;One&gt;** wants to update [App &amp; Crashes](https://app.lobu.ai/acme/topic/app-crashes):",
		);
	});

	it("drops the reason paragraph and the review link", () => {
		const body =
			"**A watcher** wants to create Slow &amp; Loading.\n" +
			"- Entity type: topic\n" +
			'\nA watcher proposes creating topic "Slow &amp; Loading".\n' +
			"\n[Review in Lobu](https://app.lobu.ai/acme/runs/44)";
		expect(notificationSummaryMarkdown(body)).toBe(
			"**A watcher** wants to create Slow &amp; Loading.",
		);
	});

	it("keeps a plain generic body that has no detail lines", () => {
		expect(
			notificationSummaryMarkdown(
				"A queued action on GitHub is waiting for your review.\n" +
					"\nReview: [Review in Lobu](https://app.lobu.ai/acme/runs/46)",
			),
		).toBe("A queued action on GitHub is waiting for your review.");
	});

	it("rejoins a summary sentence that wraps across lines", () => {
		expect(
			notificationSummaryMarkdown("**An agent** wants to merge\nDuplicate Person (#12)."),
		).toBe("**An agent** wants to merge Duplicate Person (#12).");
	});

	it("skips leading blank lines before the summary", () => {
		expect(notificationSummaryMarkdown("\n\n**A watcher** wants to merge X.")).toBe(
			"**A watcher** wants to merge X.",
		);
	});

	it("returns null when there is no renderable prose", () => {
		expect(notificationSummaryMarkdown(null)).toBeNull();
		expect(notificationSummaryMarkdown(undefined)).toBeNull();
		expect(notificationSummaryMarkdown("")).toBeNull();
		expect(notificationSummaryMarkdown("   \n  ")).toBeNull();
		expect(notificationSummaryMarkdown("- Entity id: 886")).toBeNull();
		expect(
			notificationSummaryMarkdown("[Review in Lobu](https://app.lobu.ai/acme/runs/42)"),
		).toBeNull();
	});
});

