import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { InlineMarkdownText } from "./markdown-text";
import { notificationSummaryMarkdown } from "@/lib/notification-summary";

/**
 * End-to-end for the timeline card preview: a real server notification body in,
 * rendered inline nodes out. Guards the actual reported bug — raw `**` and
 * `[label](url)` showing as literal text in the notification list.
 */
describe("InlineMarkdownText notification summary", () => {
	const body =
		"**An agent** wants to merge [905319918039@s.whatsapp.net](https://app.lobu.ai/buremba/person/member-0faa51dac0).\n" +
		"- Entity id: 886\n- Winner entity id: 315\n" +
		"\n[Review in Lobu](https://app.lobu.ai/buremba/memory?run_ids=42)";

	it("renders bold and links as elements, not literal markdown", () => {
		const summary = notificationSummaryMarkdown(body);
		expect(summary).not.toBeNull();
		const { container } = render(<InlineMarkdownText text={summary as string} />);

		// The bug: these must never survive as visible characters.
		expect(container.textContent).not.toContain("**");
		expect(container.textContent).not.toContain("](");

		expect(screen.getByText("An agent").tagName).toBe("STRONG");
		const link = screen.getByRole("link", {
			name: "905319918039@s.whatsapp.net",
		});
		expect(link).toHaveAttribute(
			"href",
			"https://app.lobu.ai/buremba/person/member-0faa51dac0",
		);
	});

	it("shows only the summary — detail lines and the review link stay out of the card", () => {
		const summary = notificationSummaryMarkdown(body);
		const { container } = render(<InlineMarkdownText text={summary as string} />);

		expect(container.textContent).toBe(
			"An agent wants to merge 905319918039@s.whatsapp.net.",
		);
		expect(container.textContent).not.toContain("Entity id");
		expect(container.textContent).not.toContain("Review in Lobu");
	});

	it("collapses to inline nodes so the card can clamp it as text", () => {
		const { container } = render(<InlineMarkdownText text="**Bold** and plain" />);
		// A block <p> would break line-clamp on the wrapping div.
		expect(container.querySelector("p")).toBeNull();
	});

	it("renders an escaped entity name literally instead of as markdown", () => {
		// Server escapes `*`/`[` before they reach us; the name must read back
		// exactly, with no emphasis applied and no backslashes leaking through.
		const { container } = render(
			<InlineMarkdownText text="wants to delete \\*Urgent\\* \\[click\\]" />,
		);
		expect(container.textContent).toBe("wants to delete *Urgent* [click]");
		expect(container.querySelector("em")).toBeNull();
		expect(container.querySelector("a")).toBeNull();
	});
});

