 * Trusting by notification *type* is not enough: the generic approval branch
 * interpolates a connection name, and rows written before the body escaping
 * existed are still in `events` and can never be re-escaped. Validating the
 * resolved href covers both, and still lets our own `[Name](/org/person/x)`
 * entity permalinks stay clickable.
 */
const inlineComponentsOwnLinksOnly: Components = {
	...inlineComponents,
	a: ({ href, children }) =>
		isOwnAppHref(href) ? (
			<a
				href={href}
				target="_blank"
				rel="noopener noreferrer"
				className="font-medium text-primary underline underline-offset-2"
			>
				{children}
			</a>
		) : (
			<>{children}</>
		),
};

export const InlineMarkdownText: FC<{
	text: string;
	className?: string;
	/**
	 * "app-links" keeps anchors whose href resolves to this app and strips every
	 * external one — for server-composed bodies (approvals). "strip" is the
	 * default and emits no anchors at all: safe for arbitrary agent-authored text.
	 */
	linkPolicy?: "app-links" | "strip";
}> = ({ text, className, linkPolicy = "strip" }) => {
	return (
		<span className={cn("break-words", className)}>
			<ReactMarkdown
				remarkPlugins={[remarkGfm]}
				components={
					linkPolicy === "app-links"
						? inlineComponentsOwnLinksOnly
						: inlineComponentsNoLinks
				}
			>
				{text}
			</ReactMarkdown>
		</span>
	);
};

