	"currency",
	"date",
	"url",
	"enum",
	"boolean",
	"number",
	"auto",
	"text",
]);

class TemplateValidationError extends Error {}

function fail(path: string, message: string): never {
	throw new TemplateValidationError(`json_template${path}: ${message}`);
