async function getOrgAdminUserIds(organizationId: string): Promise<string[]> {
	const sql = getDb();
	const rows = await sql<{ userId: string }>`
    SELECT "userId"
    FROM "member"
    WHERE "organizationId" = ${organizationId}
      AND role IN ('admin', 'owner')
  `;
	return rows.map((r) => r.userId);
}

