import { describe, expect, test } from "bun:test";
import {
	type ActionApprovalDetails,
	buildActionApprovalCard,
	buildApprovalActions,
} from "../../notifications/triggers";

/**
 * Actions are declared ONCE and projected to every surface. Before this, the
 * Slack/Telegram card built its own Approve/Reject buttons from `runId` while
 * the in-app feed tried to re-derive the run from notification metadata — and
 * failed, because approvals store `resource_type: "event"`. One declaration
 * means a surface cannot silently lose the buttons.
 */

const FIELD_CHANGE: ActionApprovalDetails = {
	kind: "entity_field_change",
	actorLabel: "Watcher One",
	entityId: 7,
	entityType: "topic",
	entityName: "App Crashes",
	fields: { severity: "critical" },
	current: { severity: "high" },
	reason: "Watcher proposes updating severity (currently set by you).",
};

const ENTITY_MERGE: ActionApprovalDetails = {
	kind: "entity_change",
	operation: "merge",
	actorLabel: "An agent",
	entityId: 886,
	entityType: "person",
	entityName: "905319918039@s.whatsapp.net",
	proposal: {},
	reason: "No deterministic identity rule proves this merge.",
};

describe("approval actions declaration", () => {
	test("declares approve/reject plus the review link for a structured approval", () => {
		const actions = buildApprovalActions({
			runId: 42,
			approvalUrl: "https://app.lobu.ai/acme/runs/42",
			details: FIELD_CHANGE,
		});

		expect(actions).toEqual([
			{ kind: "approve_run", label: "Approve", style: "primary", runId: 42 },
			{ kind: "reject_run", label: "Reject", style: "danger", runId: 42 },
			{
				kind: "link",
				label: "Review in Lobu",
				url: "https://app.lobu.ai/acme/runs/42",
			},
		]);
	});

	test("declares the same actions for an entity_change approval", () => {
		const actions = buildApprovalActions({
			runId: 747847,
			approvalUrl: "/buremba/memory?run_ids=747847",
			details: ENTITY_MERGE,
		});

		expect(actions.map((a) => a.kind)).toEqual([
			"approve_run",
			"reject_run",
			"link",
		]);
		// The run id rides the declaration — no surface re-derives it from a URL.
		expect(actions[0]).toMatchObject({ runId: 747847 });
		expect(actions[1]).toMatchObject({ runId: 747847 });
	});

	test("omits the mutations when there is no run to act on", () => {
		const actions = buildApprovalActions({
			approvalUrl: "https://app.lobu.ai/acme/runs/42",
			details: FIELD_CHANGE,
		});

		expect(actions.map((a) => a.kind)).toEqual(["link"]);
	});

	test("declares nothing for an unstructured approval", () => {
		expect(buildApprovalActions({ runId: 42 })).toEqual([]);
	});

	test("the Slack card is built from the same declaration", () => {
		const card = buildActionApprovalCard({
			runId: 42,
			approvalUrl: "https://app.lobu.ai/acme/runs/42",
			details: FIELD_CHANGE,
		});
		const actionsBlock = (
			card as { children: Array<{ type?: string; children?: unknown[] }> }
		).children.find((c) => c.type === "actions");

		// Three buttons on the card == three declared actions.
		expect(actionsBlock?.children).toHaveLength(3);
	});
});

