/**
 * Ephemeral: emit one structured approval notification through the REAL
 * trigger so the browser can exercise the declared-actions path end to end.
 */
import { notifyActionApprovalNeeded } from "./src/notifications/triggers";

const orgId = process.env.SEED_ORG_ID;
const runId = Number(process.env.SEED_RUN_ID);
if (!orgId || !Number.isFinite(runId)) {
	throw new Error("SEED_ORG_ID and SEED_RUN_ID are required");
}

await notifyActionApprovalNeeded({
	orgId,
	runId,
	actionKey: "entity_change",
	approvalUrl: `/local-install/memory?run_ids=${runId}`,
	details: {
		kind: "entity_change",
		operation: "merge",
		actorLabel: "An agent",
		entityId: 886,
		entityType: "person",
		entityName: "905319918039@s.whatsapp.net",
		proposal: {},
		reason: "No configured deterministic identity rule proves this merge.",
	},
});

console.log(`seeded approval notification for run ${runId}`);
process.exit(0);

