import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { fireEvent, render, screen } from "@testing-library/react";
import type { ReactNode } from "react";
import { describe, expect, it, vi } from "vitest";
import { HomeAttentionTimeline } from "./home-attention-timeline";

/**
 * Approval cards render from the LIVE run state the server joins through the
 * notification's proposal-event pointer (run_id + approval_status +
 * approval_inline). Before this, the feed inferred a run from
 * resource_type === "run" — but approvals store "event", so every card fell
 * back to a bare "Review & approve" link while Slack got real buttons, and a
 * card stayed actionable-looking forever after the run was decided.
 */

const { approve, reject, peekOpen } = vi.hoisted(() => ({
	approve: vi.fn(),
	reject: vi.fn(),
	peekOpen: vi.fn(),
}));

vi.mock("@tanstack/react-router", () => ({
	useNavigate: () => vi.fn(),
	Link: ({ children }: { children: ReactNode }) => children,
}));
vi.mock("@/components/peek/notification-peek-context", () => ({
	useNotificationPeek: () => ({ item: null, open: peekOpen, close: vi.fn() }),
}));
vi.mock("@/hooks/use-org-context", () => ({
	useOrgContext: () => ({ orgContext: "acme" }),
}));
vi.mock("@/lib/api/notifications", () => ({
	useMarkNotificationRead: () => ({ mutate: vi.fn() }),
}));
vi.mock("@/lib/auth-state", () => ({
	useAuthState: () => ({ session: { user: { id: "user-1" } } }),
}));
vi.mock("@/lib/api/connections", async (importOriginal) => ({
	...(await importOriginal<Record<string, unknown>>()),
	useApproveRun: () => ({ mutate: approve, isPending: false }),
	useRejectRun: () => ({ mutate: reject, isPending: false }),
}));

const APPROVAL_BASE = {
	kind: "notification",
	status: "action_approval_needed",
	unread: true,
	body: "A Behavior wants to merge duplicates.",
};

vi.mock("@/lib/api/activity", async (importOriginal) => ({
	...(await importOriginal<Record<string, unknown>>()),
	useActivityFeed: () => ({
		data: [
			{
				...APPROVAL_BASE,
				id: "notification-90",
				at: "2026-07-27T12:00:00.000Z",
				title: "Pending merge",
				href: "/acme/memory?run_ids=747847",
				notification_id: 90,
				run_id: 747847,
				approval_status: "pending",
				approval_inline: true,
			},
			{
				...APPROVAL_BASE,
				id: "notification-91",
				at: "2026-07-27T12:01:00.000Z",
				title: "Decided merge",
				href: "/acme/memory?run_ids=747848",
				notification_id: 91,
				run_id: 747848,
				approval_status: "approved",
				approval_inline: true,
			},
			{
				// A non-entity approval kind (e.g. manage_behaviors config change):
				// pending, but its executor is a settings form, not one-click.
				...APPROVAL_BASE,
				id: "notification-92",
				at: "2026-07-27T12:02:00.000Z",
				title: "Behavior change",
				href: "/acme/agents/a1/behaviors/7?run_id=747849",
				notification_id: 92,
				run_id: 747849,
				approval_status: "pending",
				approval_inline: false,
			},
		],
		isLoading: false,
		isError: false,
	}),
}));

function renderTimeline() {
	const client = new QueryClient({
		defaultOptions: { queries: { retry: false } },
	});
	return render(
		<QueryClientProvider client={client}>
			<HomeAttentionTimeline owner="acme" filter="notifications" />
		</QueryClientProvider>,
	);
}

describe("approval cards render live run state", () => {
	it("shows inline Approve/Reject only for the pending inline-approvable card", () => {
		renderTimeline();

		expect(screen.getAllByRole("button", { name: /^approve$/i })).toHaveLength(
			1,
		);
		expect(screen.getAllByRole("button", { name: /^reject$/i })).toHaveLength(
			1,
		);
	});

	it("shows the decided outcome instead of buttons for a resolved approval", () => {
		renderTimeline();

		expect(screen.getByText("Approved")).toBeTruthy();
	});

	it("keeps the review-page CTA for a pending approval without an inline executor", () => {
		renderTimeline();

		// notificationActionLabel's CTA, not inline buttons.
		expect(screen.getByText("Review & approve")).toBeTruthy();
	});

	it("opens the peek pane from Review instead of navigating away", () => {
		renderTimeline();

		fireEvent.click(screen.getByRole("button", { name: "Review" }));

		expect(peekOpen).toHaveBeenCalledWith({
			href: "/acme/memory?run_ids=747847",
			title: "Pending merge",
			runId: 747847,
		});
	});
});

